import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify'
import { atLeast, listUsersWithAccess, resolveAccess, type Access } from '../vaults/permissions.js'
import { OkfValidationError } from './okf.js'
import { logSecurityEvent } from '../auth/security-events.js'
import { notify } from '../notifications/notify.js'
import {
  createNote,
  listRevisions,
  purgeRevision,
  revertNote,
  listNotes,
  listTrash,
  readNote,
  renameNote,
  restoreNote,
  softDeleteNote,
  splitPath,
  updateNote,
} from './store.js'

type VaultReq = FastifyRequest<{ Params: { id: string; '*': string } }>

/** Resolves access or replies 404 — no access must be indistinguishable from no vault. */
async function guard(req: VaultReq, reply: FastifyReply, needed: Access): Promise<boolean> {
  const access = await resolveAccess(req.user!.id, req.params.id)
  if (!atLeast(access, needed)) {
    await reply.code(404).send({ error: 'not found' })
    return false
  }
  return true
}

export function noteRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.setErrorHandler((err, req, reply) => {
    if (err instanceof OkfValidationError) {
      return reply.code(err.message.includes('already exists') ? 409 : 400).send({ error: err.message })
    }
    throw err
  })

  app.get<{ Params: { id: string; '*': string } }>('/vaults/:id/tree', async (req, reply) => {
    if (!(await guard(req as VaultReq, reply, 'read'))) return
    const rows = await listNotes(req.params.id)
    const byType: Record<string, typeof rows> = {}
    for (const row of rows) (byType[row.type] ??= []).push(row)
    return byType
  })

  app.post<{
    Params: { id: string; '*': string }
    Body: { type: string; name: string; frontmatter?: Record<string, unknown>; body?: string }
  }>(
    '/vaults/:id/notes',
    {
      schema: {
        body: {
          type: 'object',
          required: ['type', 'name'],
          properties: {
            type: { type: 'string', minLength: 1, maxLength: 100 },
            name: { type: 'string', minLength: 1, maxLength: 200 },
            frontmatter: { type: 'object' },
            body: { type: 'string' },
          },
        },
      },
    },
    async (req, reply) => {
      if (!(await guard(req as VaultReq, reply, 'edit'))) return
      return createNote(req.params.id, req.body, { type: 'user', id: req.user!.id })
    },
  )

  app.get<{ Params: { id: string; '*': string } }>('/vaults/:id/notes/*', async (req, reply) => {
    if (!(await guard(req, reply, 'read'))) return
    splitPath(req.params['*'])
    const note = await readNote(req.params.id, req.params['*'])
    if (!note) return reply.code(404).send({ error: 'note not found' })
    return { path: note.row.path, frontmatter: note.frontmatter, body: note.body, updatedAt: note.row.updatedAt }
  })

  app.put<{
    Params: { id: string; '*': string }
    Body: { frontmatter?: Record<string, unknown>; body?: string }
  }>(
    '/vaults/:id/notes/*',
    {
      schema: {
        body: {
          type: 'object',
          properties: { frontmatter: { type: 'object' }, body: { type: 'string' } },
        },
      },
    },
    async (req, reply) => {
      if (!(await guard(req, reply, 'edit'))) return
      splitPath(req.params['*'])
      const updated = await updateNote(req.params.id, req.params['*'], req.body, {
        type: 'user',
        id: req.user!.id,
      })
      if (!updated) return reply.code(404).send({ error: 'note not found' })
      return updated
    },
  )

  app.post<{ Params: { id: string; '*': string }; Body: { from: string; to: string } }>(
    '/vaults/:id/notes-rename',
    {
      schema: {
        body: {
          type: 'object',
          required: ['from', 'to'],
          properties: {
            from: { type: 'string' },
            to: { type: 'string', minLength: 1, maxLength: 200 },
          },
        },
      },
    },
    async (req, reply) => {
      if (!(await guard(req as VaultReq, reply, 'edit'))) return
      splitPath(req.body.from)
      const renamed = await renameNote(req.params.id, req.body.from, req.body.to)
      if (!renamed) return reply.code(404).send({ error: 'note not found' })
      return renamed
    },
  )

  app.delete<{ Params: { id: string; '*': string } }>(
    '/vaults/:id/notes/*',
    async (req, reply) => {
      if (!(await guard(req, reply, 'edit'))) return
      splitPath(req.params['*'])
      const deleted = await softDeleteNote(req.params.id, req.params['*'], {
        type: 'user',
        id: req.user!.id,
      })
      if (!deleted) return reply.code(404).send({ error: 'note not found' })
      return { status: 'trashed', id: deleted.id }
    },
  )

  app.get<{ Params: { id: string; '*': string } }>('/vaults/:id/trash', async (req, reply) => {
    if (!(await guard(req as VaultReq, reply, 'edit'))) return
    return listTrash(req.params.id)
  })

  app.post<{ Params: { id: string; noteId: string; '*': string } }>(
    '/vaults/:id/trash/:noteId/restore',
    async (req, reply) => {
      if (!(await guard(req as unknown as VaultReq, reply, 'edit'))) return
      const restored = await restoreNote(req.params.id, req.params.noteId)
      if (!restored) return reply.code(404).send({ error: 'trashed note not found' })
      return restored
    },
  )

  app.get<{ Params: { id: string; '*': string } }>(
    '/vaults/:id/history/*',
    async (req, reply) => {
      // Audit rule: history requires edit, not merely read.
      if (!(await guard(req, reply, 'edit'))) return
      splitPath(req.params['*'])
      const revisions = await listRevisions(req.params.id, req.params['*'])
      if (!revisions) return reply.code(404).send({ error: 'note not found' })
      return revisions
    },
  )

  app.post<{ Params: { id: string; '*': string }; Body: { revisionId: string } }>(
    '/vaults/:id/revert/*',
    {
      schema: {
        body: {
          type: 'object',
          required: ['revisionId'],
          properties: { revisionId: { type: 'string', format: 'uuid' } },
        },
      },
    },
    async (req, reply) => {
      if (!(await guard(req, reply, 'edit'))) return
      splitPath(req.params['*'])
      const reverted = await revertNote(req.params.id, req.params['*'], req.body.revisionId, {
        type: 'user',
        id: req.user!.id,
      })
      if (!reverted) return reply.code(404).send({ error: 'note or revision not found' })
      await notifyRevert(req.params.id, req.params['*'], req.user!.id)
      return reverted
    },
  )

  app.delete<{ Params: { id: string; revisionId: string; '*': string } }>(
    '/vaults/:id/revisions/:revisionId',
    async (req, reply) => {
      // Hard purge: owner or admin only (spec 6).
      const access = await resolveAccess(req.user!.id, req.params.id)
      const isAdmin = req.user!.role === 'admin'
      if (access !== 'owner' && !isAdmin) return reply.code(404).send({ error: 'not found' })
      const purged = await purgeRevision(req.params.id, req.params.revisionId)
      if (!purged) return reply.code(404).send({ error: 'revision not found' })
      await logSecurityEvent({
        type: 'revision_purged',
        actorUserId: req.user!.id,
        detail: { vaultId: req.params.id, revisionId: req.params.revisionId },
      })
      return { status: 'purged' }
    },
  )
}

/** Notifications spec trigger 3: a note you have access to was reverted. */
async function notifyRevert(vaultId: string, path: string, actorUserId: string): Promise<void> {
  const users = await listUsersWithAccess(vaultId)
  for (const userId of users) {
    if (userId === actorUserId) continue
    await notify({
      recipientId: userId,
      type: 'note_reverted',
      entityType: 'vault',
      entityId: vaultId,
      message: `Note ${path} was reverted to an earlier version.`,
    })
  }
}

import { mkdir, readFile, rename, rm, unlink, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { and, asc, desc, eq, isNotNull, isNull } from 'drizzle-orm'
import { db } from '../db/client.js'
import { noteLinks, noteRevisions, notes } from '../db/schema.js'
import { config } from '../config.js'
import { scheduleEmbedding } from '../search/embedding-queue.js'
import {
  OkfValidationError,
  extractWikilinks,
  parseNote,
  serializeNote,
  validateNote,
  isSlug,
  type Frontmatter,
} from './okf.js'

export type NoteRow = typeof notes.$inferSelect
export type RevisionRow = typeof noteRevisions.$inferSelect

/** Who performed a write — recorded in the audit trail (spec 6). */
export interface Actor {
  type: 'user' | 'mcp' | 'collab'
  id?: string
}

const SYSTEM_ACTOR: Actor = { type: 'collab' }

/** Records a revision unless identical to the note's latest one (dedupes
 * the MCP-immediate + collab-debounced double-write of the same state). */
async function recordRevision(
  noteId: string,
  action: string,
  frontmatter: unknown,
  body: string,
  actor: Actor,
): Promise<void> {
  const last = (
    await db
      .select({ frontmatter: noteRevisions.frontmatter, body: noteRevisions.body })
      .from(noteRevisions)
      .where(eq(noteRevisions.noteId, noteId))
      .orderBy(desc(noteRevisions.createdAt))
      .limit(1)
  )[0]
  if (last && last.body === body && JSON.stringify(last.frontmatter) === JSON.stringify(frontmatter)) {
    return
  }
  await db.insert(noteRevisions).values({
    noteId,
    actorType: actor.type,
    actorId: actor.id,
    action,
    frontmatter: frontmatter as Record<string, unknown>,
    body,
  })
}

function vaultDir(vaultId: string): string {
  return join(config.dataDir, 'vaults', vaultId)
}

function noteFile(vaultId: string, path: string): string {
  return join(vaultDir(vaultId), `${path}.md`)
}

function trashFile(vaultId: string, noteId: string): string {
  return join(vaultDir(vaultId), '.trash', `${noteId}.md`)
}

/** Drizzle wraps driver errors; the Postgres code may sit on `cause`. */
function isUniqueViolation(err: unknown): boolean {
  let current: unknown = err
  while (current instanceof Error) {
    if ((current as { code?: string }).code === '23505') return true
    current = current.cause
  }
  return false
}

export function splitPath(path: string): { type: string; name: string } {
  const parts = path.split('/')
  if (parts.length !== 2 || !isSlug(parts[0]!) || !isSlug(parts[1]!)) {
    throw new OkfValidationError(`invalid note path: ${path}`)
  }
  return { type: parts[0]!, name: parts[1]! }
}

async function atomicWrite(file: string, content: string): Promise<void> {
  await mkdir(dirname(file), { recursive: true })
  const tmp = `${file}.tmp`
  await writeFile(tmp, content, 'utf8')
  await rename(tmp, file)
}

/**
 * OKF convention: every type folder carries an auto-generated index.md
 * listing its notes. Derived output — regenerated on any change, never
 * indexed as a note itself.
 */
async function regenIndex(vaultId: string, type: string): Promise<void> {
  const rows = await db
    .select({ path: notes.path, name: notes.name })
    .from(notes)
    .where(and(eq(notes.vaultId, vaultId), eq(notes.type, type), isNull(notes.deletedAt)))
    .orderBy(asc(notes.name))
  const file = join(vaultDir(vaultId), type, 'index.md')
  if (rows.length === 0) {
    await unlink(file).catch(() => {})
    return
  }
  const lines = rows.map((r) => `- [[${r.path}]]`)
  await atomicWrite(file, `# ${type}\n\n${lines.join('\n')}\n`)
}

export async function createNote(
  vaultId: string,
  input: { type: string; name: string; frontmatter?: Record<string, unknown>; body?: string },
  actor: Actor = SYSTEM_ACTOR,
): Promise<NoteRow> {
  const frontmatter: Frontmatter = {
    timestamp: new Date().toISOString(),
    ...input.frontmatter,
    type: input.type,
  }
  const body = input.body ?? ''
  validateNote(input.type, input.name, frontmatter, body)
  const path = `${input.type}/${input.name}`
  let row: NoteRow
  try {
    const inserted = await db
      .insert(notes)
      .values({ vaultId, type: input.type, name: input.name, path, frontmatter, body })
      .returning()
    row = inserted[0]!
  } catch (err) {
    if (isUniqueViolation(err)) {
      throw new OkfValidationError(`a note already exists at ${path}`)
    }
    throw err
  }
  await atomicWrite(noteFile(vaultId, path), serializeNote({ frontmatter, body }))
  await regenIndex(vaultId, input.type)
  await syncLinks(row.id, body)
  scheduleEmbedding(row.id)
  await recordRevision(row.id, 'create', frontmatter, body, actor)
  return row
}

/** Replaces the note's EXTRACTED link rows from its current wikilinks. */
export async function syncNoteLinks(noteId: string, body: string): Promise<void> {
  return syncLinks(noteId, body)
}

async function syncLinks(noteId: string, body: string): Promise<void> {
  await db.delete(noteLinks).where(eq(noteLinks.sourceNoteId, noteId))
  const targets = extractWikilinks(body)
  if (targets.length > 0) {
    await db
      .insert(noteLinks)
      .values(targets.map((targetPath) => ({ sourceNoteId: noteId, targetPath })))
      .onConflictDoNothing()
  }
}

export async function getLiveNote(vaultId: string, path: string): Promise<NoteRow | null> {
  const rows = await db
    .select()
    .from(notes)
    .where(and(eq(notes.vaultId, vaultId), eq(notes.path, path), isNull(notes.deletedAt)))
  return rows[0] ?? null
}

/** Reads a note's current content from disk (canonical source). */
export async function readNote(
  vaultId: string,
  path: string,
): Promise<{ row: NoteRow; frontmatter: Frontmatter; body: string } | null> {
  const row = await getLiveNote(vaultId, path)
  if (!row) return null
  const raw = await readFile(noteFile(vaultId, path), 'utf8')
  const parsed = parseNote(raw)
  return { row, frontmatter: parsed.frontmatter, body: parsed.body }
}

export async function updateNote(
  vaultId: string,
  path: string,
  input: { frontmatter?: Record<string, unknown>; body?: string },
  actor: Actor = SYSTEM_ACTOR,
): Promise<NoteRow | null> {
  const row = await getLiveNote(vaultId, path)
  if (!row) return null
  const frontmatter: Frontmatter = {
    ...(input.frontmatter ?? (row.frontmatter as Frontmatter)),
    type: row.type,
  }
  const body = input.body ?? row.body
  validateNote(row.type, row.name, frontmatter, body)
  const [updated] = await db
    .update(notes)
    .set({ frontmatter, body, updatedAt: new Date() })
    .where(eq(notes.id, row.id))
    .returning()
  await atomicWrite(noteFile(vaultId, path), serializeNote({ frontmatter, body }))
  await syncLinks(row.id, body)
  scheduleEmbedding(row.id)
  await recordRevision(row.id, 'update', frontmatter, body, actor)
  return updated!
}

export async function renameNote(
  vaultId: string,
  from: string,
  toName: string,
): Promise<NoteRow | null> {
  const row = await getLiveNote(vaultId, from)
  if (!row) return null
  if (!isSlug(toName)) throw new OkfValidationError(`invalid name slug: ${toName}`)
  const toPath = `${row.type}/${toName}`
  if (await getLiveNote(vaultId, toPath)) {
    throw new OkfValidationError(`a note already exists at ${toPath}`)
  }
  const [updated] = await db
    .update(notes)
    .set({ name: toName, path: toPath, updatedAt: new Date() })
    .where(eq(notes.id, row.id))
    .returning()
  await rename(noteFile(vaultId, from), noteFile(vaultId, toPath))
  await regenIndex(vaultId, row.type)
  return updated!
}

/** Soft delete (spec 6: one consistent delete behavior): file → .trash, row keeps everything. */
export async function softDeleteNote(
  vaultId: string,
  path: string,
  actor: Actor = SYSTEM_ACTOR,
): Promise<NoteRow | null> {
  const row = await getLiveNote(vaultId, path)
  if (!row) return null
  const [updated] = await db
    .update(notes)
    .set({ deletedAt: new Date(), updatedAt: new Date() })
    .where(eq(notes.id, row.id))
    .returning()
  await mkdir(join(vaultDir(vaultId), '.trash'), { recursive: true })
  await rename(noteFile(vaultId, path), trashFile(vaultId, row.id))
  await regenIndex(vaultId, row.type)
  await recordRevision(row.id, 'delete', row.frontmatter, row.body, actor)
  return updated!
}

export async function restoreNote(vaultId: string, noteId: string): Promise<NoteRow | null> {
  const rows = await db
    .select()
    .from(notes)
    .where(and(eq(notes.id, noteId), eq(notes.vaultId, vaultId), isNotNull(notes.deletedAt)))
  const row = rows[0]
  if (!row) return null
  if (await getLiveNote(vaultId, row.path)) {
    throw new OkfValidationError(`a live note already exists at ${row.path}`)
  }
  const [updated] = await db
    .update(notes)
    .set({ deletedAt: null, updatedAt: new Date() })
    .where(eq(notes.id, row.id))
    .returning()
  await mkdir(dirname(noteFile(vaultId, row.path)), { recursive: true })
  await rename(trashFile(vaultId, row.id), noteFile(vaultId, row.path))
  await regenIndex(vaultId, row.type)
  scheduleEmbedding(row.id)
  return updated!
}

export async function listNotes(vaultId: string): Promise<
  Array<Pick<NoteRow, 'id' | 'path' | 'type' | 'name' | 'frontmatter' | 'updatedAt'>>
> {
  return db
    .select({
      id: notes.id,
      path: notes.path,
      type: notes.type,
      name: notes.name,
      frontmatter: notes.frontmatter,
      updatedAt: notes.updatedAt,
    })
    .from(notes)
    .where(and(eq(notes.vaultId, vaultId), isNull(notes.deletedAt)))
    .orderBy(asc(notes.path))
}

export async function listTrash(vaultId: string): Promise<
  Array<Pick<NoteRow, 'id' | 'path' | 'type' | 'name' | 'deletedAt'>>
> {
  return db
    .select({
      id: notes.id,
      path: notes.path,
      type: notes.type,
      name: notes.name,
      deletedAt: notes.deletedAt,
    })
    .from(notes)
    .where(and(eq(notes.vaultId, vaultId), isNotNull(notes.deletedAt)))
}

/** Change history for a note, newest first (edit/owner only — enforced by callers). */
export async function listRevisions(
  vaultId: string,
  path: string,
): Promise<RevisionRow[] | null> {
  const row = await getLiveNote(vaultId, path)
  if (!row) return null
  return db
    .select()
    .from(noteRevisions)
    .where(eq(noteRevisions.noteId, row.id))
    .orderBy(desc(noteRevisions.createdAt))
}

/** Restores a note to a recorded revision (a new attributed write). */
export async function revertNote(
  vaultId: string,
  path: string,
  revisionId: string,
  actor: Actor,
): Promise<NoteRow | null> {
  const row = await getLiveNote(vaultId, path)
  if (!row) return null
  const revision = (
    await db
      .select()
      .from(noteRevisions)
      .where(and(eq(noteRevisions.id, revisionId), eq(noteRevisions.noteId, row.id)))
  )[0]
  if (!revision) return null
  const updated = await updateNote(
    vaultId,
    path,
    { frontmatter: revision.frontmatter as Record<string, unknown>, body: revision.body },
    actor,
  )
  if (updated) {
    const newest = (
      await db
        .select({ id: noteRevisions.id })
        .from(noteRevisions)
        .where(eq(noteRevisions.noteId, row.id))
        .orderBy(desc(noteRevisions.createdAt))
        .limit(1)
    )[0]
    if (newest) {
      await db
        .update(noteRevisions)
        .set({ action: 'revert' })
        .where(eq(noteRevisions.id, newest.id))
    }
  }
  return updated
}

/**
 * Hard purge (spec 6): permanently removes one recorded revision — for
 * accidentally-committed secrets, where "recoverable" is the wrong
 * property. Owner/admin only — enforced by callers.
 */
export async function purgeRevision(vaultId: string, revisionId: string): Promise<boolean> {
  const rows = await db
    .select({ revisionId: noteRevisions.id })
    .from(noteRevisions)
    .innerJoin(notes, eq(notes.id, noteRevisions.noteId))
    .where(and(eq(noteRevisions.id, revisionId), eq(notes.vaultId, vaultId)))
  if (rows.length === 0) return false
  await db.delete(noteRevisions).where(eq(noteRevisions.id, revisionId))
  return true
}

/** Permanently removes a trashed note (used by purge policies later). */
export async function purgeNote(vaultId: string, noteId: string): Promise<boolean> {
  const rows = await db
    .select()
    .from(notes)
    .where(and(eq(notes.id, noteId), eq(notes.vaultId, vaultId), isNotNull(notes.deletedAt)))
  const row = rows[0]
  if (!row) return false
  await db.delete(notes).where(eq(notes.id, row.id))
  await rm(trashFile(vaultId, row.id), { force: true })
  return true
}

export class ApiError extends Error {
  status: number
  body: unknown

  constructor(status: number, body: unknown) {
    const message =
      typeof body === 'object' && body !== null && 'error' in body && typeof (body as { error: unknown }).error === 'string'
        ? (body as { error: string }).error
        : `Request failed (${status})`
    super(message)
    this.status = status
    this.body = body
  }
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`/api${path}`, {
    ...init,
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...init?.headers },
  })
  const body = await res.json().catch(() => undefined)
  if (!res.ok) throw new ApiError(res.status, body)
  return body as T
}

/** Test-only helper: builds a real Response for stubbed fetch calls. */
export function mockJsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  })
}
